import type {FC} from 'react';
import React from 'react';

import {HelpMark, getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import type {
    TrackerSelectItemContentProps,
    TrackerSelectItemValueBase,
} from '../../../../components/TrackerSelect/types';
import {cnFieldsSelect} from '../../FieldsSelect.classname';

import {itemTooltipPlacement} from './constants';
import {defaultMessages, fieldHintMessages} from './i18n';

type FieldsActionsProps<Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase> = {
    scope?: 'issue' | 'projects';
} & TrackerSelectItemContentProps<Value>;

export const FieldsActions: FC<FieldsActionsProps> = (props) => {
    const {item, scope} = props;
    const config = getConfig();
    const {t} = useLocalizedString({...defaultMessages, ...fieldHintMessages}, config.lang);

    const contentId: string = scope === 'projects' ? `${item.id}-projects` : item.id;

    const content = t(contentId);

    // No translation for the key => don't show a help mark
    if (content === contentId) {
        return null;
    }

    return (
        <HelpMark
            aria-label={t('show-help')}
            className={cnFieldsSelect('help-tooltip')}
            popoverProps={{
                placement: itemTooltipPlacement,
            }}
        >
            {content}
        </HelpMark>
    );
};
